"use client"

import { type KeyboardEvent, useState } from "react"

import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "./card"

/** One sentence on what the chart shows, the field every chart in the set exports. */
export const description = "A calendar heatmap that shows daily activity over half a year"

const WEEKS = 26
const DAY_MS = 24 * 60 * 60 * 1000
// The last column ends on a Sunday. Weeks run Monday to Sunday, top to bottom.
const LAST_DAY = Date.UTC(2026, 8, 27)
const FIRST_DAY = LAST_DAY - (WEEKS * 7 - 1) * DAY_MS
const CELL = 12
const GAP = 3
const PITCH = CELL + GAP
const LEFT = 28
const TOP = 16
// Level 0 is an empty day. Levels 1 to 4 deepen the first chart colour.
const OPACITY = [0, 0.3, 0.55, 0.8, 1]

// Example data from an integer hash, so every engine, server and browser alike, draws the same cells.
const chartData = Array.from({ length: WEEKS * 7 }, (_, index) => {
  const date = new Date(FIRST_DAY + index * DAY_MS)
  const weekend = date.getUTCDay() === 0 || date.getUTCDay() === 6
  const noise = ((Math.imul(index + 1, 2654435761) >>> 0) % 1000) / 1000
  return { date, sessions: Math.round(noise * (weekend ? 3 : 11)) }
})

const busiest = Math.max(...chartData.map((day) => day.sessions))
const total = chartData.reduce((sum, day) => sum + day.sessions, 0)
const level = (sessions: number) => (sessions === 0 ? 0 : Math.ceil((sessions / busiest) * 4))

const dayFormat = new Intl.DateTimeFormat("en-US", { weekday: "short", month: "short", day: "numeric", timeZone: "UTC" })
const monthFormat = new Intl.DateTimeFormat("en-US", { month: "short", timeZone: "UTC" })

// A month label sits over the first column that starts in a new month. A label
// with fewer than three columns before the next one is dropped, so none collide.
const starts = Array.from({ length: WEEKS }, (_, week) => chartData[week * 7]?.date)
  .map((date, week, all) => ({ week, date, previous: all[week - 1] }))
  .filter(({ date, previous }) => date && (!previous || date.getUTCMonth() !== previous.getUTCMonth()))
const months = starts.filter(({ week }, index) => (starts[index + 1]?.week ?? WEEKS) - week >= 3)

const fill = (sessions: number) => (sessions === 0 ? "var(--muted)" : "var(--chart-1)")

// Left and right move a week, up and down move a day, as the grid reads.
const STEPS = new Map([
  ["ArrowLeft", -7],
  ["ArrowRight", 7],
  ["ArrowUp", -1],
  ["ArrowDown", 1],
])
const lastIndex = chartData.length - 1

/** A calendar heatmap of daily sessions over 26 weeks. Pointing at or tapping a day reads its count. */
export function ChartHeatmapCalendar() {
  const [selected, setSelected] = useState<number | null>(null)
  const day = selected === null ? undefined : chartData[selected]

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    let next: number | undefined
    if (event.key === "Home") next = 0
    else if (event.key === "End") next = lastIndex
    else if (STEPS.has(event.key)) next = Math.min(lastIndex, Math.max(0, (selected ?? lastIndex) + (selected === null ? 0 : (STEPS.get(event.key) ?? 0))))
    if (next === undefined) return
    event.preventDefault()
    setSelected(next)
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle>Calendar Heatmap</CardTitle>
        <CardDescription>Daily sessions, April to September</CardDescription>
      </CardHeader>
      <CardContent>
        {/* A pointer, a tap or the arrow keys pick a day; the footer below reads it aloud. */}
        <div
          role="group"
          tabIndex={0}
          aria-label={`Daily sessions over ${WEEKS} weeks: ${total} in all, at most ${busiest} in one day. Use the arrow keys to read each day.`}
          onKeyDown={onKeyDown}
          onPointerLeave={(event) => {
            if (event.pointerType === "mouse") setSelected(null)
          }}
          className="rounded-md outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          <svg
            aria-hidden="true"
            viewBox={`0 0 ${LEFT + WEEKS * PITCH} ${TOP + 7 * PITCH}`}
            className="h-auto w-full"
          >
            {months.map(({ week, date }) => (
              <text key={week} x={LEFT + week * PITCH} y={10} className="fill-muted-foreground" fontSize={9}>
                {date ? monthFormat.format(date) : null}
              </text>
            ))}
            {["Mon", "Wed", "Fri"].map((label, index) => (
              <text key={label} x={0} y={TOP + index * 2 * PITCH + CELL - 2} className="fill-muted-foreground" fontSize={9}>
                {label}
              </text>
            ))}
            {chartData.map((entry, index) => (
              <rect
                key={entry.date.getTime()}
                x={LEFT + Math.floor(index / 7) * PITCH}
                y={TOP + (index % 7) * PITCH}
                width={CELL}
                height={CELL}
                rx={2.5}
                fill={fill(entry.sessions)}
                fillOpacity={entry.sessions === 0 ? 1 : OPACITY[level(entry.sessions)]}
                stroke={selected === index ? "var(--foreground)" : "none"}
                onPointerEnter={(event) => {
                  if (event.pointerType !== "touch") setSelected(index)
                }}
                onClick={() => setSelected(index)}
              >
                <title>{`${entry.sessions} sessions on ${dayFormat.format(entry.date)}`}</title>
              </rect>
            ))}
          </svg>
        </div>
        <div className="mt-3 flex items-center justify-end gap-1 text-xs text-muted-foreground">
          <span className="mr-1">Less</span>
          {OPACITY.map((opacity, index) => (
            <svg key={opacity} viewBox="0 0 12 12" aria-hidden="true" className="size-3">
              <rect width={12} height={12} rx={2.5} fill={index === 0 ? "var(--muted)" : "var(--chart-1)"} fillOpacity={index === 0 ? 1 : opacity} />
            </svg>
          ))}
          <span className="ml-1">More</span>
        </div>
      </CardContent>
      <CardFooter className="flex-col items-start gap-2 text-sm">
        <div aria-live="polite" className="leading-none font-medium tabular-nums">
          {day ? `${day.sessions} sessions on ${dayFormat.format(day.date)}` : `${total.toLocaleString("en-US")} sessions in ${WEEKS} weeks`}
        </div>
        <div className="leading-none text-muted-foreground">Point at, tap or use the arrow keys on a day to read its count</div>
      </CardFooter>
    </Card>
  )
}
